def transform(grid):
    out = [row[:] for row in grid]
    sevens = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 7]
    nines = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 9]
    rows = sorted(set(r for r, _ in sevens + nines))
    seven_cols = [c for _, c in sevens]
    nine_cols = [c for _, c in nines]
    lo = min(max(seven_cols), max(nine_cols))
    hi = max(min(seven_cols), min(nine_cols))
    red_cols = {c for c in range(lo + 1, hi) if any(grid[r][c] == 0 for r in range(len(grid)))}
    dr = min(r for r, _ in nines) - min(r for r, _ in sevens)
    dc = min(nine_cols) - min(seven_cols)
    for r, c in sevens + nines:
        out[r][c] = 6
    for r, c in sevens:
        out[r + dr][c + dc] = 7
    for r in rows:
        for c in red_cols:
            out[r][c] = 2
    return out
